85	/** The first command in a comment, or nothing. Any line may carry it. */
86	export function parseCommentCommand(body: string): ParsedCommentCommand {
87	  if (!body) return NOTHING;
88	  for (const rawLine of body.split("\n")) {
89	    const parsed = parseCommandLine(rawLine);
90	    if (parsed !== undefined) return parsed;
91	  }
92	  return NOTHING;
93	}
