95	/** One line that reads as a command, with the line itself for telling a person what it was. */
96	export interface CommentCommandLine {
97	  /** The line as it was written, trimmed. */
98	  line: string;
99	  /** What the parser makes of it — a command, or the error that stops it. */
100	  command: ParsedCommentCommand;
101	}
