103	/**
104	 * How a notice names one command line.
105	 *
106	 * A malformed line is shown as it was written, because the notice's job is to tell a
107	 * person what their comment asked for: `/engineer fix it` does not read as `//`, and
108	 * the line is the thing they must rewrite. Everything else is named by what the
109	 * machinery would have run, `/stop` or `/reviewer`.
110	 *
111	 * Shared by the two notices that name commands -- the in-progress/commands guard and
112	 * the stop receipt -- so `/stop` + `/reviewer` reads the same in both.
113	 */
114	export function commandLabel(command: CommentCommandLine): string {
115	  return command.command.error !== "" ? command.line : command.command.control ? `/${command.command.control}` : `/${command.command.agent}`;
116	}
