118	/**
119	 * Every command a comment asks for, in the order they appear.
120	 *
121	 * `parseCommentCommand` answers "what does this comment ask for" and returns the first,
122	 * because the machinery acts on one request per comment. This answers "how many", so a
123	 * guard can refuse a comment that asks for two: the second would be read by nobody, and
124	 * which one wins is not visible on the page.
125	 *
126	 * A line the parser rejects is counted too. `parseCommentCommand` stops at the FIRST
127	 * command line, so a malformed one above a valid one loses the valid one as thoroughly
128	 * as a well-formed one above it would — only the error on the first line is reported,
129	 * and the person is never told the second request existed. Counting it is what lets the
130	 * guard say so.
131	 *
132	 * Strict, like the parser it shares its line reader with — a command is a line that
133	 * begins with one. A directive quoted inside somebody's prose (`> /engineer`) is not a
134	 * request the machinery would act on, so it is not a second command here either.
135	 */
136	export function commandsIn(body: string): CommentCommandLine[] {
137	  const found: CommentCommandLine[] = [];
138	  if (!body) return found;
139	  for (const rawLine of body.split("\n")) {
140	    const parsed = parseCommandLine(rawLine);
141	    if (parsed !== undefined) found.push({ line: rawLine.trim(), command: parsed });
142	  }
143	  return found;
144	}
